class Solution {
    public int[] amountPainted(int[][] paint) {
        int[] painted = new int[50001];
        int[] res = new int[paint.length];
        for (int d = 0; d < paint.length; d++) {
            int start = paint[d][0], end = paint[d][1], fresh = 0;
            while (start < end) {
                if (painted[start] == 0) {
                    fresh++;
                    painted[start] = end;
                    start++;
                } else {
                    start = painted[start];
                }
            }
            res[d] = fresh;
        }
        return res;
    }
}
